import{_ as a,o as r,c as t,a5 as l}from"./chunks/framework.Cooo9kuv.js";const b=JSON.parse('{"title":"WordPress 弹窗广告插件 — Popup Ads","description":"","frontmatter":{"标题":"WordPress 弹窗广告插件 — Popup Ads – tcad_tanchuang","日期":"2026-07-12T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["wordpress主题插件"],"标签":["Cookie控制","HTML过滤","WordPress","双语界面","响应式设计","广告管理","弹窗广告","弹窗插件","自定义CSS"]},"headers":[{"level":2,"title":"插件简介","slug":"插件简介","link":"#插件简介","children":[]},{"level":2,"title":"功能特性","slug":"功能特性","link":"#功能特性","children":[{"level":3,"title":"PC 端与移动端独立弹窗位","slug":"pc-端与移动端独立弹窗位","link":"#pc-端与移动端独立弹窗位","children":[]},{"level":3,"title":"HTML 与文本双模式内容","slug":"html-与文本双模式内容","link":"#html-与文本双模式内容","children":[]},{"level":3,"title":"Cookie 关闭计时器","slug":"cookie-关闭计时器","link":"#cookie-关闭计时器","children":[]},{"level":3,"title":"动画展示效果","slug":"动画展示效果","link":"#动画展示效果","children":[]},{"level":3,"title":"自定义 CSS","slug":"自定义-css","link":"#自定义-css","children":[]},{"level":3,"title":"中英双语后台","slug":"中英双语后台","link":"#中英双语后台","children":[]},{"level":3,"title":"全局控制与卸载清理","slug":"全局控制与卸载清理","link":"#全局控制与卸载清理","children":[]},{"level":3,"title":"水印文字","slug":"水印文字","link":"#水印文字","children":[]},{"level":3,"title":"安全性设计","slug":"安全性设计","link":"#安全性设计","children":[]},{"level":3,"title":"响应式适配","slug":"响应式适配","link":"#响应式适配","children":[]}]},{"level":2,"title":"使用说明","slug":"使用说明","link":"#使用说明","children":[{"level":3,"title":"第一步：安装插件","slug":"第一步-安装插件","link":"#第一步-安装插件","children":[]},{"level":3,"title":"第二步：配置全局设置","slug":"第二步-配置全局设置","link":"#第二步-配置全局设置","children":[]},{"level":3,"title":"第三步：配置弹窗内容","slug":"第三步-配置弹窗内容","link":"#第三步-配置弹窗内容","children":[]},{"level":3,"title":"第四步：保存并验证","slug":"第四步-保存并验证","link":"#第四步-保存并验证","children":[]}]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":2,"title":"反馈与支持","slug":"反馈与支持","link":"#反馈与支持","children":[]},{"level":2,"title":"更新日志","slug":"更新日志","link":"#更新日志","children":[{"level":3,"title":"v2.1.4（2026-06-27）","slug":"v2-1-4-2026-06-27","link":"#v2-1-4-2026-06-27","children":[]},{"level":3,"title":"v2.1.0（2026-06-18）","slug":"v2-1-0-2026-06-18","link":"#v2-1-0-2026-06-18","children":[]}]}],"relativePath":"md/wordpress主题插件/WordPress 弹窗广告插件 — Popup Ads - tcad_tanchuang.md","filePath":"md/wordpress主题插件/WordPress 弹窗广告插件 — Popup Ads - tcad_tanchuang.md"}'),o={name:"md/wordpress主题插件/WordPress 弹窗广告插件 — Popup Ads - tcad_tanchuang.md"};function i(n,e,d,s,h,c){return r(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="wordpress-弹窗广告插件-—-popup-ads" tabindex="-1">WordPress 弹窗广告插件 — Popup Ads <a class="header-anchor" href="#wordpress-弹窗广告插件-—-popup-ads" aria-label="Permalink to &quot;WordPress 弹窗广告插件 — Popup Ads&quot;">​</a></h1><blockquote><p>为 WordPress 网站提供 PC 端与移动端独立配置的弹窗广告位，支持 HTML 代码和纯文本两种内容模式，内置 Cookie 关闭计时器避免反复打扰访客，支持自定义 CSS 与中英双语后台管理。</p></blockquote><p><strong>版本</strong>：v2.1.4<br><strong>适配</strong>：WordPress 5.0+<br><strong>PHP</strong>：≥ 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/1334c707-c71c-4b26-ba8a-a6ed24d10d15.png" alt=""></p><p>本插件用于在 WordPress 网站前台展示弹窗广告或公告内容。PC 端与移动端各提供三个弹窗位置（中间弹窗、左下角弹窗、右下角弹窗），六个位置互不影响，可分别配置内容、标题、尺寸和启用状态。</p><p>插件内置两种内容输入模式：HTML 模式适合嵌入广告代码或图文内容，系统自动过滤 script 标签和事件属性保障安全；文本模式将所有输入进行转义处理，适合展示纯文本公告。访客关闭弹窗后，插件通过 Cookie 记录并在设定时长内不再重复显示，避免过度干扰用户体验。</p><p>后台管理界面支持中英文双语切换，提供全局开关、移动端显示控制、自定义 CSS、水印文字等集中化设置，每个弹窗位置还可独立控制水印显示。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="pc-端与移动端独立弹窗位" tabindex="-1">PC 端与移动端独立弹窗位 <a class="header-anchor" href="#pc-端与移动端独立弹窗位" aria-label="Permalink to &quot;PC 端与移动端独立弹窗位&quot;">​</a></h3><p>插件为 PC 端和移动端分别提供三个弹窗位置，共六个独立配置单元：</p><table tabindex="0"><thead><tr><th>端</th><th>位置</th><th>说明</th></tr></thead><tbody><tr><td>PC 端</td><td>中间弹窗</td><td>页面居中弹出，适合重要公告或大型广告</td></tr><tr><td>PC 端</td><td>左下角弹窗</td><td>从左下角滑入，适合轻量推广信息</td></tr><tr><td>PC 端</td><td>右下角弹窗</td><td>从右下角滑入，适合轻量推广信息</td></tr><tr><td>移动端</td><td>中间弹窗</td><td>移动端居中弹出，自适应屏幕宽度</td></tr><tr><td>移动端</td><td>左下角弹窗</td><td>移动端左下角滑入</td></tr><tr><td>移动端</td><td>左下角弹窗</td><td>移动端左下角滑入</td></tr></tbody></table><p>每个弹窗位置均可独立设置内容、标题、宽度、高度和水印显示，互不干扰。</p><h3 id="html-与文本双模式内容" tabindex="-1">HTML 与文本双模式内容 <a class="header-anchor" href="#html-与文本双模式内容" aria-label="Permalink to &quot;HTML 与文本双模式内容&quot;">​</a></h3><p>每个弹窗支持两种内容模式，可在后台随时切换：</p><p>— <strong>HTML 模式</strong>：适合嵌入广告代码、图片、iframe 等 HTML 内容。系统自动过滤 script 标签、onclick 等事件属性和 javascript: 伪协议链接，仅保留安全的 HTML 标签和属性，确保网站不被恶意代码注入；</p><p>— <strong>文本模式</strong>：适合展示纯文本公告。输入内容会自动转义 HTML 特殊字符并保留换行，以带标题栏的公告卡片样式呈现，视觉效果清晰规范。</p><h3 id="cookie-关闭计时器" tabindex="-1">Cookie 关闭计时器 <a class="header-anchor" href="#cookie-关闭计时器" aria-label="Permalink to &quot;Cookie 关闭计时器&quot;">​</a></h3><p>访客点击弹窗关闭按钮后，插件写入浏览器 Cookie，在设定的秒数内该弹窗不再显示：</p><p>— 关闭计时时长可在后台全局配置，范围 1 至 86400 秒（24 小时）；<br> — 每个弹窗位使用独立的 Cookie 名称，关闭某个位置的弹窗不影响其他位置；<br> — 计时到期后弹窗自动恢复显示，无需访客手动操作。</p><h3 id="动画展示效果" tabindex="-1">动画展示效果 <a class="header-anchor" href="#动画展示效果" aria-label="Permalink to &quot;动画展示效果&quot;">​</a></h3><p>弹窗出现时带有平滑动画，提升视觉体验而不显突兀：</p><p>— 左下角和右下角弹窗从屏幕底部向上滑入，动画时长 800 毫秒；<br> — 中间弹窗从顶部向下滑入至屏幕中央，动画时长 800 毫秒；<br> — 关闭弹窗时带 400 毫秒淡出效果。</p><h3 id="自定义-css" tabindex="-1">自定义 CSS <a class="header-anchor" href="#自定义-css" aria-label="Permalink to &quot;自定义 CSS&quot;">​</a></h3><p>后台提供自定义 CSS 文本域，输入样式代码后自动注入前台页面：</p><p>— 建议使用 <code>.tcad-</code> 选择器限定作用域，避免影响网站其他元素；<br> — 支持实时预览，保存设置后立即生效；<br> — 系统自动过滤可能引入安全风险的 style 标签和 script 相关内容。</p><h3 id="中英双语后台" tabindex="-1">中英双语后台 <a class="header-anchor" href="#中英双语后台" aria-label="Permalink to &quot;中英双语后台&quot;">​</a></h3><p>管理界面支持中文和英文两种语言，后台顶部下拉框一键切换：</p><p>— 所有界面文案、开关状态提示、占位符说明均支持双语；<br> — 语言偏好保存在插件配置中，切换后全局生效。</p><h3 id="全局控制与卸载清理" tabindex="-1">全局控制与卸载清理 <a class="header-anchor" href="#全局控制与卸载清理" aria-label="Permalink to &quot;全局控制与卸载清理&quot;">​</a></h3><p>— 顶部总开关可一键启用或禁用全部弹窗，方便临时关闭所有广告展示；<br> — 移动端独立开关控制是否在手机等移动设备上显示弹窗；<br> — 卸载时清理配置选项：开启后，删除插件时将自动清除所有数据库配置记录，不留残留数据。</p><h3 id="水印文字" tabindex="-1">水印文字 <a class="header-anchor" href="#水印文字" aria-label="Permalink to &quot;水印文字&quot;">​</a></h3><p>— 全局设置广告提示文字（默认为「广告」），显示在弹窗关闭按钮旁；<br> — 每个弹窗位置可独立控制是否显示水印文字；<br> — HTML 模式和文本模式均支持水印显示，位置自适应弹窗布局。</p><h3 id="安全性设计" tabindex="-1">安全性设计 <a class="header-anchor" href="#安全性设计" aria-label="Permalink to &quot;安全性设计&quot;">​</a></h3><p>— HTML 模式通过白名单机制过滤标签和属性，仅允许安全的 HTML 元素通过；<br> — 自动移除 script 标签、on* 事件属性、javascript: 伪协议；<br> — 文本模式对所有输入进行 HTML 实体转义；<br> — 管理页面使用 WordPress Nonce 机制防止 CSRF 攻击；<br> — 所有用户输入经过 WordPress 内置消毒函数处理。</p><h3 id="响应式适配" tabindex="-1">响应式适配 <a class="header-anchor" href="#响应式适配" aria-label="Permalink to &quot;响应式适配&quot;">​</a></h3><p>— 弹窗在移动端自动调整最大宽度，避免撑破屏幕；<br> — 中间弹窗在小屏设备上限制为 90vw；<br> — 文本模式公告卡片在小屏下自动缩小字体和间距。</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 <code>tcad_tanchuang</code> 文件夹上传至网站 <code>wp-content/plugins/</code> 目录，进入 WordPress 后台「插件」页面，找到「弹窗广告位」并点击启用。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-30.png" alt=""></p><h3 id="第二步-配置全局设置" tabindex="-1">第二步：配置全局设置 <a class="header-anchor" href="#第二步-配置全局设置" aria-label="Permalink to &quot;第二步：配置全局设置&quot;">​</a></h3><p>进入后台「设置 → 弹窗广告位」页面：</p><p>— 页面顶部总开关默认开启，可一键关闭所有弹窗；<br> — 选择后台界面语言（中文 / English）；<br> — 设置移动端是否显示弹窗；<br> — 设置关闭后隐藏时长（秒），默认 60 秒；<br> — 填写广告提示文字（水印），默认为「广告」；<br> — 如需自定义弹窗样式，在「自定义 CSS」文本域中输入 CSS 代码。</p><h3 id="第三步-配置弹窗内容" tabindex="-1">第三步：配置弹窗内容 <a class="header-anchor" href="#第三步-配置弹窗内容" aria-label="Permalink to &quot;第三步：配置弹窗内容&quot;">​</a></h3><p>在「PC 端弹窗广告」和「移动端弹窗广告」两个卡片中分别配置：</p><p>— 为每个弹窗位选择内容模式（HTML 或文本）；<br> — 填写弹窗标题（文本模式下显示在公告栏顶部）；<br> — 设置弹窗宽度和高度（支持 px、em、rem、%、vw、vh 单位）；<br> — 选择是否显示水印文字；<br> — 在内容输入框中填写广告代码或文本内容；<br> — 开启弹窗的启用开关。</p><h3 id="第四步-保存并验证" tabindex="-1">第四步：保存并验证 <a class="header-anchor" href="#第四步-保存并验证" aria-label="Permalink to &quot;第四步：保存并验证&quot;">​</a></h3><p>— 点击页面底部「保存设置」按钮；<br> — 访问网站前台，确认弹窗是否按预期出现在对应位置；<br> — 点击关闭按钮测试 Cookie 机制，在设定时长内刷新页面确认弹窗不再出现；<br> — 在移动设备上验证移动端弹窗的显示效果。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 本插件展示的是弹窗层（CSS fixed 定位），并非浏览器原生弹窗，不会被浏览器弹窗拦截器阻止；<br> — HTML 模式会自动过滤 script 标签和事件属性，如需嵌入完整 JavaScript 代码请使用其他专业方案；<br> — 弹窗尺寸单位支持 px、em、rem、%、vw、vh，留空则使用 CSS 默认值自适应；<br> — 移动端弹窗位仅在移动设备上生效（通过 WordPress 内置的 wp_is_mobile() 函数判断），PC 端弹窗位同理仅在桌面设备上显示；<br> — 关闭按钮写入的 Cookie 路径为网站根路径（<code>path=/</code>），确保全站范围内生效；<br> — 自定义 CSS 输入框中的代码会直接输出到前台页面，请确保语法正确以免影响页面样式。</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.top<br> — 作者网站：softbangong.com<br> — 邮箱：<a href="mailto:yunjuliangpin@163.com" target="_blank" rel="noreferrer">yunjuliangpin@163.com</a><br> — 邮箱：<a href="mailto:softbangong@gmail.com" target="_blank" rel="noreferrer">softbangong@gmail.com</a></p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v2-1-4-2026-06-27" tabindex="-1">v2.1.4（2026-06-27） <a class="header-anchor" href="#v2-1-4-2026-06-27" aria-label="Permalink to &quot;v2.1.4（2026-06-27）&quot;">​</a></h3><p>— 新增中英双语后台管理界面，支持中文和英文一键切换；<br> — 新增自定义 CSS 功能，可在后台直接注入自定义样式代码；<br> — 新增文本模式，支持纯文本公告展示并自动转义 HTML 字符；<br> — 新增每个弹窗位独立的水印显示开关；<br> — 新增卸载时清理配置选项，可选择是否保留数据库配置记录；<br> — 优化 HTML 模式安全过滤机制，增强 script 标签和事件属性过滤；<br> — 优化弹窗动画效果，修复移动端弹窗尺寸计算问题；<br> — 优化后台管理界面布局，采用卡片式设计提升操作体验。</p><h3 id="v2-1-0-2026-06-18" tabindex="-1">v2.1.0（2026-06-18） <a class="header-anchor" href="#v2-1-0-2026-06-18" aria-label="Permalink to &quot;v2.1.0（2026-06-18）&quot;">​</a></h3><p>— 新增 PC 端与移动端独立弹窗位分离，共六个可配置位置；<br> — 新增 Cookie 关闭计时器，支持自定义隐藏时长 1 至 86400 秒；<br> — 新增弹窗自定义宽高配置，支持多种 CSS 单位；<br> — 新增全局总开关和移动端独立开关；<br> — 新增响应式适配，移动端弹窗自动缩放。</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/3045.html" target="_blank" rel="noreferrer">https://www.softbangong.com/3045.html</a></p>',60)])])}const u=a(o,[["render",i]]);export{b as __pageData,u as default};
